SELECT budget_period_id, start_date, end_date, amount
FROM budget_period
WHERE user_id = #{userId}
  AND start_date <= #{date}
  AND end_date >= #{date}

SELECT MAX(end_date)
FROM budget_period
WHERE user_id = #{userId}

SELECT figure_id, figure_name, kind, paid_date, amount
FROM (
    SELECT f.figure_id AS figure_id, f.name AS figure_name, 'DEPOSIT' AS kind,
           f.deposit_paid_at AS paid_date, f.deposit_amount AS amount
    FROM figure f
    WHERE f.user_id = #{userId}
      AND f.payment_type = 'DEPOSIT'
      AND f.deposit_paid_at BETWEEN #{startDate} AND #{endDate}
    UNION ALL
    SELECT f.figure_id, f.name, 'FULL', f.paid_at, f.price * f.quantity
    FROM figure f
    WHERE f.user_id = #{userId}
      AND f.payment_type = 'FULL'
      AND f.paid_at BETWEEN #{startDate} AND #{endDate}
    UNION ALL
    SELECT f.figure_id, f.name, 'BALANCE', f.paid_at,
           GREATEST(CAST(f.price * f.quantity AS SIGNED) - CAST(f.deposit_amount AS SIGNED), 0)
    FROM figure f
    WHERE f.user_id = #{userId}
      AND f.payment_type = 'DEPOSIT'
      AND f.paid_at BETWEEN #{startDate} AND #{endDate}
) spending
ORDER BY paid_date DESC, figure_id DESC

SELECT figure_id, status, price, quantity, deposit_amount
FROM figure
WHERE user_id = #{userId}
  AND figure_id IN

    #{figureId}
